const cards=document.querySelectorAll(".card"),modal=document.getElementById("itemModal"),modalSlide=document.querySelector(".modal-slide"),backButton=document.getElementById("backButton"),customizeButton=document.getElementById("customizeButton");let currentSlideIndex=0,currentSlides=[];function openModal(e){currentSlides=e,currentSlideIndex=0,modal.style.display="flex",updateModalSlide()}function updateModalSlide(){modalSlide.src=currentSlides[currentSlideIndex].src}document.querySelectorAll(".item").forEach((e=>{const t=e.querySelectorAll(".slideshow .slide");e.addEventListener("click",(()=>{const n=e.querySelector("#name").textContent,l=e.querySelector("#price").textContent;openModal(Array.from(t)),localStorage.setItem("nameID",n),localStorage.setItem("priceID",l)}))})),backButton.addEventListener("click",(()=>{modal.style.display="none"})),customizeButton.addEventListener("click",(()=>{const e=currentSlides.map((e=>e.src));localStorage.setItem("selectedImages",JSON.stringify(e)),window.location.href="customization.html"})),modal.addEventListener("click",(e=>{e.target===modal&&(modal.style.display="none")}));const menuBtn=document.getElementById("menu-btn"),menu=document.getElementById("menu"),closeBtn=document.getElementById("close-btn");menuBtn.addEventListener("click",(()=>{menu.style.display="block"})),closeBtn.addEventListener("click",(()=>{menu.style.display="none"})),document.addEventListener("click",(e=>{menu.contains(e.target)||e.target===menuBtn||(menu.style.display="none")}));